import {icon} from './icons.js';
import {KEYSTONE_RARITIES} from './loot.js';
import {CRAFT_OPERATIONS} from './crafting.js';
import {KEYSTONE_CRAFT_OPERATIONS,RIFT_MODIFIERS,modifierValue,riftBonuses,keystoneCraftEligibility} from './keystones.js';

const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEYSTONE_CRAFT_COPY={
  transmute:'Normal → magic with 1–2 new modifiers.',augment:'Add a second modifier to a magic keystone.',regal:'Promote a two-modifier magic keystone to rare.',
  alchemy:'Normal → rare with 3–4 new modifiers.',chaos:'Reroll all 3–4 modifiers on a rare keystone.',exalt:'Add a fourth modifier to a rare keystone.',
  scour:'Remove modifiers and return a magic or rare keystone to normal.',divine:'Reroll modifier values while keeping rarity and modifier types.'
};

export function keystoneDetails(key){
  const b=riftBonuses(key);
  return `<div class="keystone-detail rarity-${key.rarity}"><span class="item-rarity">${KEYSTONE_RARITIES[key.rarity]} · KEYSTONE · LEVEL ${key.itemLevel}</span><h3>${esc(key.name)}</h3><p class="dialog-description">Four monster waves, then a powerful rift guardian. Each wave starts as soon as the previous wave is cleared.</p><div class="rift-rewards"><div><strong>${key.itemLevel+b.itemLevel}</strong><span>Reward item level</span></div><div><strong>+${b.quantity}%</strong><span>Item quantity</span></div><div><strong>+${b.rarity}%</strong><span>Item rarity</span></div></div><h4>Rift difficulty</h4><div class="rift-difficulty">${[['Monster life',b.life],['Monster damage',b.damage],['Movement & attack speed',b.speed],['Monsters per wave',b.pack],['Damage reduction',b.reduction],['Critical chance (points)',b.critical]].filter(([,v])=>v).map(([label,value])=>`<div><span>${label}</span><b>+${value}%</b></div>`).join('')}</div><h4>Rolled modifiers · ${key.modifiers.length}</h4><ul class="rift-modifiers">${key.modifiers.length?key.modifiers.map(m=>`<li><strong>${RIFT_MODIFIERS[m.id].name}</strong><span>+${modifierValue(m)}% ${RIFT_MODIFIERS[m.id].label}</span></li>`).join(''):'<li>No rolled modifiers. This rift still has stronger monsters and a final boss.</li>'}</ul><p class="small-description">Every rolled modifier raises reward item level, quantity, and rarity. Quantity grants extra item rolls; rarity improves the chance of better equipment and does not guarantee a rarity.</p><p class="rift-rule">One entry. Opening consumes the keystone; entering consumes the portal. Death or teleporting out ends the run. Reloading resumes an unfinished run; rifts pause while you are away.</p></div>`;
}

export function keystonePouch(s,page=0){
  const pages=Math.max(1,Math.ceil(s.keystones.length/12));page=Math.max(0,Math.min(pages-1,page));
  const items=s.keystones.slice(page*12,page*12+12);
  return `<section class="panel secondary-panel keystone-pouch"><div class="view-section-title"><div><h2>Keystone pouch <span class="capacity">${s.keystones.length}</span></h2><p>Keystones come only from defeated foes and always pass your loot filter. Orbs can modify a found keystone at the altar.</p></div>${icon('gem')}</div><div class="keystone-grid">${items.map(k=>{const b=riftBonuses(k);return `<button class="keystone-card rarity-${k.rarity}" data-keystone="${k.id}"><span class="item-rarity">${KEYSTONE_RARITIES[k.rarity]} · LEVEL ${k.itemLevel}</span>${icon('gem')}<strong>${esc(k.name)}</strong><span>${k.modifiers.length} modifiers · reward level ${k.itemLevel+b.itemLevel}</span><small>+${b.quantity}% quantity · +${b.rarity}% rarity</small><b>Inspect ${icon('arrow')}</b></button>`;}).join('')||'<p class="village-empty">No keystones yet. Defeat monsters in expeditions to find one; currency orbs cannot create a keystone.</p>'}</div>${pages>1?`<div class="pouch-pagination"><button class="button" data-key-page="${page-1}" ${page===0?'disabled':''}>Previous</button><span>${page+1} / ${pages}</span><button class="button" data-key-page="${page+1}" ${page===pages-1?'disabled':''}>Next</button></div>`:''}</section>`;
}

export function keystoneAltar(s,selectedId=null){
  const selected=s.keystones.find(k=>k.id===selectedId)||s.keystones[0]||null;
  const choices=s.keystones.slice(0,12).map(k=>`<button class="altar-keystone-choice rarity-${k.rarity} ${selected?.id===k.id?'selected':''}" data-altar-key="${k.id}" aria-pressed="${selected?.id===k.id}"><span>${KEYSTONE_RARITIES[k.rarity]} · Lv. ${k.itemLevel}</span><strong>${esc(k.name)}</strong><small>${k.modifiers.length} modifier${k.modifiers.length===1?'':'s'}</small></button>`).join('');
  const operations=selected?KEYSTONE_CRAFT_OPERATIONS.map(opId=>{const op=CRAFT_OPERATIONS[opId],reason=keystoneCraftEligibility(opId,selected),owned=s.orbs[opId]||0,disabled=!!reason||owned<1;return `<article class="keystone-orb-operation ${disabled?'unavailable':''}">${icon(op.icon)}<div><strong>${esc(op.name)}</strong><p>${KEYSTONE_CRAFT_COPY[opId]}</p><small>${reason||`${owned} owned · consumes 1`}</small></div><button class="button" data-craft-keystone="${opId}" data-key-id="${selected.id}" ${disabled?'disabled':''}>Apply · ${owned}</button></article>`;}).join(''):'';
  return `<section class="panel secondary-panel keystone-altar"><div class="view-section-title"><div><h2>The keystone altar</h2><p>Only monsters drop keystones. Select one from your pouch, then spend an orb to shape its rarity, modifiers, or rolls. No orb can create a keystone.</p></div>${icon('sparkles')}</div>${selected?`<div class="keystone-altar-layout"><div><h3>Choose a found keystone</h3><div class="altar-keystone-list">${choices}</div></div><div class="altar-workbench"><div class="altar-selection rarity-${selected.rarity}"><span class="item-rarity">SELECTED · ${KEYSTONE_RARITIES[selected.rarity]} · LEVEL ${selected.itemLevel}</span><strong>${esc(selected.name)}</strong><small>${selected.modifiers.length} modifiers · item level cannot be changed by crafting</small></div><div class="keystone-orb-grid">${operations}</div><p class="small-description">Unique keystones are loot-only and cannot be created or scoured. A Divine Orb can reroll their modifier values.</p></div></div>`:'<div class="altar-empty">'+icon('gem')+'<div><strong>The altar needs a keystone.</strong><p>Find one as loot in an expedition. Your orbs remain available until a dropped keystone is selected.</p></div></div>'}</section>`;
}

export function villagePanel(s,page=0,selectedId=null){
  const last=s.lastRift,status=last?.status;
  const notice=last?status==='cleared'?'Rift conquered. Your collected rewards are safe.':status==='failed'?'You fell in the rift. That portal is permanently closed.':status==='lost'?'The saved rift could not be restored. Its portal remains consumed.':'You left the rift. That portal is permanently closed.':'';
  return `<section class="village-welcome panel"><div><span class="eyebrow">VILLAGE · A PLACE TO RETURN TO</span><h2>Rest beneath the lanterns.</h2><p>The wild can wait. Prepare your gear, shape a found keystone, and choose your next journey.</p><span class="village-safe">${icon('shield')} Safe in town · combat and offline farming paused</span></div><div class="village-services"><button class="button" data-view="forge">${icon('hammer')} Village forge</button><button class="button" data-view="inventory">${icon('bag')} Open satchel</button></div></section>${notice?`<p class="rift-result" role="status">${icon(status==='cleared'?'trophy':'info')}${notice}</p>`:''}<div class="village-routes"><section class="panel village-route"><span class="route-number">01 · THE ROAD</span><h3>Expedition entrance</h3><p>Start a fresh map of any unlocked stage. Your highest unlocked stage is ${s.maxStage}.</p><form id="village-stage-form"><label for="village-stage">Stage</label><div><input id="village-stage" name="stage" type="number" min="1" max="${s.maxStage}" step="1" value="${s.maxStage}" required><button class="button gold-button" type="submit">Begin stage ${icon('arrow')}</button></div></form><small>A fresh stage replaces your saved expedition return point.</small></section><section class="panel village-route return-route"><span class="route-number">02 · THE WAY BACK</span><h3>Return portal</h3><p>${s.returnPortal?`Stage ${s.stage} · ${esc(s.map.name)}<br>Same position, surviving monsters, and guardian progress.`:'Teleport here from an expedition to leave a return portal.'}</p><div class="portal-readout">${icon('compass')}<span>${s.returnPortal?`${s.map.progress} / ${s.map.goal} guardian progress`:'No expedition waiting'}</span></div><button class="button" data-action="resume-expedition" ${s.returnPortal?'':'disabled'}>Continue expedition ${icon('arrow')}</button></section><section class="panel village-route rift-route"><span class="route-number">03 · BEYOND THE VEIL</span><h3>Rift portal</h3><p>${s.riftPortal?`${KEYSTONE_RARITIES[s.riftPortal.rarity]} rift · level ${s.riftPortal.itemLevel}<br>${s.riftPortal.modifiers.length} modifiers · one entry remaining`:'Choose a keystone from your pouch to open a single-use portal.'}</p>${s.riftPortal?`<div class="portal-readout">${icon('gem')}<span>Keystone committed · ready to enter</span></div><button class="text-button" data-action="inspect-rift-portal">Review difficulty & rewards</button><button class="button gold-button" data-action="enter-rift">Enter rift · one use ${icon('arrow')}</button>`:'<div class="portal-readout">'+icon('lock')+'<span>No rift open</span></div>'}<small>Death or teleporting out closes the rift. Your normal expedition return point is kept.</small></section></div>${keystoneAltar(s,selectedId)}${keystonePouch(s,page)}`;
}
